import React from "react";
import { useAuth } from "../auth/AuthContext";
import { Link } from "react-router-dom";

export default function TopBar() {
  const { user, logout } = useAuth();

  const isGuest = user?.role === "guest";
  const username = user?.username || "Gast";

  return (
    <div className="fixed top-0 left-0 w-full h-10 bg-black/70 text-white flex items-center justify-between px-4 z-50 text-sm">
      <div>
        {isGuest ? (
          <Link to="/login" className="underline hover:text-blue-300">
            Login
          </Link>
        ) : (
          <button onClick={logout} className="underline hover:text-red-400">
            Logout
          </button>
        )}
      </div>
      <div>
        Angemeldet als: <span className="font-semibold">{username}</span>
      </div>
    </div>
  );
}
